import json,re,hashlib
ops={'=','!=','==','->','|','+','-','*','/','&&','||','iff','requires','in','subset_of','=>'}
toplevel={'module','version','status','parent','import','interface','dialect','law','rule','invariant','class','type','record','tensor','codec','surface','metric','hash','needle','cycle'}
cases=[('positive_rule','rule gwt.broadcast!=gwt.use'),('g9_diff_gt','rule diff>0 => ADD_OR_STRENGTHEN'),('g9_generation_gte','rule valid_generation requires count(distinct(classes))>=2 && count(executable)>=1'),('g9_if_stmt','if residual.effect {effect_intent=EffectIntent(residual);receipt=Needle.execute(effect_intent)}'),('dbl_projection','projection BindingLattice -> ClayGraph.Hyperrelation {'),('dbl_experiment','experiment DBL_E1 = baseline_static_claygraph vs scalar_hebbian vs dynamic_binding_lattice'),('dbl_hypothesis','hypothesis H_DBL_01 = \"candidate\"'),('dialect_method_sig','projection(reader:ReaderId)->Ref')]
out=[]
for name,s in cases:
    issues=[]
    stripped=s.strip()
    first=re.match(r'[A-Za-z_][A-Za-z0-9_-]*',stripped)
    first=first.group(0) if first else ''
    if first in {'projection','experiment','hypothesis','counterhypothesis','falsifier'}: issues.append(['unsupported_top_level_keyword',first])
    if first=='if': issues.append(['unsupported_control_statement','if'])
    masked=stripped.replace('>=','').replace('<=','').replace('->','').replace('=>','').replace('!=','').replace('==','')
    if '>=' in stripped: issues.append(['unsupported_operator','>='])
    elif re.search(r'(?<![-=])>(?!=)',masked): issues.append(['unsupported_operator','>'])
    if name=='dialect_method_sig' and re.search(r'\w+\(\w+:\w+\)->\w+',stripped): issues.append(['unsupported_typed_method_signature',':'])
    out.append({'case':name,'issues':issues})
flagged=sum(bool(x['issues']) for x in out)
assert flagged==7 and not out[0]['issues']
print(json.dumps({'sentinel':'CLAYCODE_GRAMMAR_PROBE_OK:7','flagged':flagged,'results':out},sort_keys=True))
